DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_restore r USING (member_id) WHERE md5(b.background_timeline::text) = r.cur_md5) <> 18 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-11-07v value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = r.tl, background_last_checked = r.checked
  FROM bt_restore r WHERE b.member_id = r.member_id AND md5(b.background_timeline::text) = r.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  restored integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5283, 5286, 5287, 5292, 5293, 5294, 5316, 5322, 5325, 5326, 5329, 5335, 5336, 5342, 5356, 5359, 5403, 5450) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO restored FROM public.mp_biography b JOIN bt_restore r USING (member_id)
   WHERE b.background_timeline IS NOT DISTINCT FROM r.tl AND b.background_last_checked IS NOT DISTINCT FROM r.checked;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 18 %, rows restored exactly %, MPs with a timeline %, entries %', changed, changed_outside, restored, with_timeline, entry_total;
  IF changed <> 18 THEN RAISE EXCEPTION 'expected exactly 18 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 18 changed', changed_outside; END IF;
  IF restored <> 18 THEN RAISE EXCEPTION 'expected 18 rows restored exactly, got %', restored; END IF;
  IF with_timeline <> 650 THEN RAISE EXCEPTION 'expected 650 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 7476 THEN RAISE EXCEPTION 'expected 7476 entries, got %', entry_total; END IF;
END $$;

COMMIT;
